		midA[biq_b2] = (1.0 - biqK / midA[biq_reso] + biqK * biqK) * norm;
		biqK = tan(M_PI * midB[biq_freq]);
		norm = 1.0 / (1.0 + biqK / midB[biq_reso] + biqK * biqK);
		midB[biq_a0] = biqK * biqK * norm;
		midB[biq_a1] = 2.0 * midB[biq_a0];
		midB[biq_a2] = midB[biq_a0];
